def apply_substitutions(replacements, text):
    # Build mapping from key to replacement string
    mapping = {}
    for key, value in replacements:
        mapping[key] = value

    cache = {}

    def expand(key):
        # Fully resolved value of a key (empty if not found); memoized
        if key not in cache:
            cache[key] = resolve(mapping.get(key, ''))
        return cache[key]

    def resolve(s):
        # Scan left to right; only a placeholder's value recurses, so recursion
        # depth is bounded by the nesting depth of the replacements.
        out = []
        pos = 0
        while pos < len(s):
            i = s.find('%', pos)
            if i == -1:
                out.append(s[pos:])
                break
            j = s.find('%', i + 1)
            if j == -1:
                out.append(s[pos:])  # Unmatched %, treat as literal
                break
            out.append(s[pos:i])
            out.append(expand(s[i + 1:j]))
            pos = j + 1
        return ''.join(out)

    return resolve(text)
